        for (c,d) in B:
            k=(a+c,b+d); C[k]=C.get(k,0)^1
    return frozenset(k for k,v in C.items() if v)
def divide_binomial(f,a,b):
    """exact division of f by (1 + x^a y^b) over GF(2) Laurent ring; returns quotient or None"""
    # choose weight so that x^a y^b has positive weight
    w=(a,b)
    key=lambda e: (e[0]*w[0]+e[1]*w[1], e)
    f=set(f); q=set()
    while f:
        lead=max(f,key=key)
        t=(lead[0]-a,lead[1]-b)   # q term: lead / (x^a y^b)
        q^={t}
        for s in [t,(t[0]+a,t[1]+b)]: f^={s}
        if f and max(key(e)[0] for e in f) < min(key(e)[0] for e in f)-10**9: break
        if len(f)>400: return None
    return frozenset(q)
